import{_ as a,o as i,c as t,b3 as n}from"./chunks/framework.VnelH-cX.js";const e="/docs-imgs/faq/SnowShot_2025-11-03_02-38-13.webp",g=JSON.parse('{"title":"Wing Shot 已损坏，无法打开","description":"","frontmatter":{},"headers":[],"relativePath":"faq/macOs/1.md","filePath":"faq/macOs/1.md","lastUpdated":1786700458000}'),p={name:"faq/macOs/1.md"};function r(h,s,l,o,d,k){return i(),t("div",null,[...s[0]||(s[0]=[n('<h1 id="wing-shot-已损坏-无法打开" tabindex="-1">Wing Shot 已损坏，无法打开 <a class="header-anchor" href="#wing-shot-已损坏-无法打开" aria-label="Permalink to &quot;Wing Shot 已损坏，无法打开&quot;">​</a></h1><p>应用需要软件签名才能避免安装后弹出“应用已损坏”的提示，但软件签名的费用昂贵，目前需要手动绕过签名进行安装。</p><p><img src="'+e+'" alt="Wing Shot 已损坏"></p><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><p>进入<strong>启动台</strong>，打开<strong>终端</strong>，输入以下命令（命令结尾包含一个空格）。</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>接着打开<strong>访达</strong>（Finder）进入<strong>应用程序</strong>目录，找到 <strong>Wing Shot</strong> 的图标，使用鼠标将图标拖入终端窗口，终端会显示以下命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /Applications/Snow</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Shot.app</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>最后，在<strong>终端</strong>按下回车键即可。</p>',9)])])}const F=a(p,[["render",r]]);export{g as __pageData,F as default};
